 void refreshParameterActivity()override{if(number==31)static_cast<DeltaMonitorProcessor&>(processor).applyPendingAlignment();refreshChoices();repaint();}
 void refreshChoices(){for(auto&c:controls)if(c->choice>=0){const auto*p=processor.state.getRawParameterValue(c->id);c->button.setToggleState(p&&int(std::lround(p->load()))==c->choice,juce::dontSendNotification);}}
 void paint(juce::Graphics&g)override{g.fillAll(juce::Colours::black);g.drawImage(art,getLocalBounds().toFloat(),juce::RectanglePlacement::stretchToFit);const juce::Graphics::ScopedSaveState save(g);g.addTransform(juce::AffineTransform::scale(getWidth()/1672.f,getHeight()/941.f));refreshChoices();if(number==29)paintLoudness(g);else if(number==30)paintSpectrum(g);else paintDelta(g);}
private:
 struct Control{juce::String id;int kind=0,choice=-1;juce::Rectangle<float>body,read;juce::ToggleButton button;ui::PhysicalValueSlider slider;juce::ComboBox combo;std::unique_ptr<juce::AudioProcessorValueTreeState::ButtonAttachment>ba;std::unique_ptr<juce::AudioProcessorValueTreeState::SliderAttachment>sa;std::unique_ptr<juce::AudioProcessorValueTreeState::ComboBoxAttachment>ca;};
 void action(const juce::String&title,juce::Rectangle<float>b,std::function<void()>f){auto c=std::make_unique<Control>();c->body=b;c->button.setButtonText(title);c->button.setName(title);c->button.setClickingTogglesState(false);c->button.onClick=std::move(f);addAndMakeVisible(c->button);look.registerButton(c->button,art,b);controls.push_back(std::move(c));}
 void choice(const char*id,int value,const char*title,juce::Rectangle<float>b){action(title,b,[this,id,value]{if(auto*p=processor.state.getParameter(id)){p->beginChangeGesture();p->setValueNotifyingHost(p->convertTo0to1(float(value)));p->endChangeGesture();}refreshParameterActivity();});controls.back()->id=id;controls.back()->choice=value;controls.back()->button.setComponentID(value==0?juce::String(id):juce::String(id)+"_"+juce::String(value));controls.back()->button.getProperties().set("analysisChoiceParameter",id);controls.back()->button.getProperties().set("analysisChoiceValue",value);for(const auto&spec:processor.parameterSpecs())if(juce::String(id)==spec.id)controls.back()->button.setName(spec.name);}
