 void dial(const char*id,float x,float y,float radius,juce::Rectangle<float>read){auto c=std::make_unique<Control>();c->id=id;c->kind=2;c->body={x-radius,y-radius,2*radius,2*radius};c->read=read;c->slider.setComponentID(id);c->slider.getProperties().set("preserveAuthoredDialRing",true);c->slider.setSliderStyle(juce::Slider::RotaryHorizontalVerticalDrag);c->slider.setRotaryParameters(juce::MathConstants<float>::pi*1.25f,juce::MathConstants<float>::pi*2.75f,true);addAndMakeVisible(c->slider);look.registerDial(c->id,juce::ImageCache::getFromMemory(OriginalArt::native_transient_png,OriginalArt::native_transient_pngSize),{268,619,134,134});for(const auto&spec:processor.parameterSpecs())if(c->id==spec.id){c->slider.setName(spec.name);c->slider.setTextValueSuffix(juce::String(" ")+spec.unit);c->slider.setDoubleClickReturnValue(true,spec.initial);c->slider.setTooltip(juce::String(spec.name)+": "+juce::String(spec.minimum)+" to "+juce::String(spec.maximum)+" "+spec.unit);}c->sa=std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(processor.state,id,c->slider);controls.push_back(std::move(c));}
 static void blank(juce::Graphics&g,juce::Rectangle<float>b){g.setColour(juce::Colour(0xff030a10));g.fillRect(b);}
 static void text(juce::Graphics&g,juce::Rectangle<float>b,const juce::String&s,float size=20){blank(g,b);g.setColour(juce::Colours::cyan);g.setFont(size);g.drawText(s,b,juce::Justification::centred);}
 static juce::String numberText(float v,bool available){return available?(v<=analysis::floorDb?juce::String("-inf"):juce::String(v,1)):juce::String("--");}
 static void meter(juce::Graphics&g,juce::Rectangle<float>b,float level,bool valid){blank(g,b);ui::paintSegmentedMeter(g,b,std::clamp((level+60.f)/60.f,0.f,1.f),valid);}
 static void trace(juce::Graphics&g,juce::Rectangle<float>b,const std::array<float,600>&values,unsigned count,unsigned cursor,float low,float high,juce::Colour colour){
    if(count==0)return;
    juce::Path path;bool connected=false;
    g.setColour(colour);
    for(unsigned i=0;i<count;++i){
        const auto ix=(cursor+600-count+i)%600;
        if(!std::isfinite(values[ix])){connected=false;continue;}
        const float x=b.getX()+b.getWidth()*i/float(std::max(1u,count-1));
        const float y=b.getBottom()-std::clamp((values[ix]-low)/(high-low),0.f,1.f)*b.getHeight();
        if(connected)path.lineTo(x,y);
        else {path.startNewSubPath(x,y);g.fillEllipse(x-1,y-1,2.f,2.f);}
        connected=true;
    }
    g.strokePath(path,juce::PathStrokeType(2));
 }
 void paintLoudness(juce::Graphics&g){const bool valid=static_cast<LoudnessLabProcessor&>(processor).readAnalysis(*loud);const auto&f=loud->measurement;const int mode=int(processor.state.getRawParameterValue("meterView")->load());const bool hold=processor.state.getRawParameterValue("peakHold")->load()>.5f;text(g,{112,174,186,25},mode==0?"INPUT PEAK":mode==1?"INPUT RMS":"INPUT VU",20);text(g,{1388,174,204,25},mode==0?"OUTPUT PEAK":mode==1?"OUTPUT RMS":"OUTPUT VU",20);text(g,{115,200,179,21},mode==2?"0 VU = -18 dBFS":"dBFS",16);text(g,{1390,200,199,21},mode==2?"0 VU = -18 dBFS":"dBFS",16);for(int side=0;side<2;++side)for(int c=0;c<2;++c){const float value=mode==1?f.rms[size_t(c)]:mode==2?f.vu[size_t(c)]-18:hold?f.heldPeak[size_t(c)]:f.samplePeak[size_t(c)];meter(g,{float(side?1375+c*117:88+c*130),227,84,319},value,valid);}const std::array<juce::Rectangle<float>,3>graphs{{{383,263,279,146},{701,263,274,146},{1010,263,279,146}}};for(auto b:graphs)blank(g,b);if(valid){if(f.integratedReady)trace(g,graphs[0],loud->integrated,loud->historyCount,loud->historyCursor,-70,0,juce::Colours::orange);trace(g,graphs[1],loud->shortTerm,loud->historyCount,loud->historyCursor,-70,0,juce::Colours::orange);trace(g,graphs[2],loud->momentary,loud->historyCount,loud->historyCursor,-70,0,juce::Colours::cyan);}text(g,{408,421,157,46},numberText(f.integrated,valid&&f.integratedReady));text(g,{726,421,157,46},numberText(f.shortTerm,valid&&f.shortReady));text(g,{1042,421,157,46},numberText(f.momentary,valid&&f.momentaryReady));text(g,{431,547,139,37},numberText(f.lra,valid&&f.lraReady));text(g,{744,547,140,37},numberText(f.truePeakEstimate,valid));text(g,{1063,547,139,37},numberText(f.crest,valid));text(g,{705,511,245,29},"8x FIR PEAK ESTIMATE",18);text(g,{889,548,95,35},"dBFS est",16);blank(g,{55,666,390,61});if(valid&&f.correlationReady){g.setColour(juce::Colours::cyan);g.fillRect(248+f.correlation*192,674.f,3.f,43.f);}text(g,{464,680,97,41},numberText(f.correlation,valid&&f.correlationReady));blank(g,{646,659,594,134});if(valid){trace(g,{648,661,590,130},loud->momentary,loud->historyCount,loud->historyCursor,-70,0,juce::Colours::cyan);trace(g,{648,661,590,130},loud->shortTerm,loud->historyCount,loud->historyCursor,-70,0,juce::Colours::orange);}text(g,{690,795,505,24},!valid?"WAITING FOR AUDIO":!f.complete?"DROPPED AUDIO: RESET I / LRA":f.capacityExceeded?"4 HOUR LIMIT: RESET I / LRA":"0 to -70 LUFS | history "+juce::String(loud->historyCount>1?loud->times[(loud->historyCursor+599)%600]-loud->times[(loud->historyCursor+600-loud->historyCount)%600]:0,1)+" s",16);}
 void paintSpectrum(juce::Graphics&g){const bool valid=static_cast<SpectrumSpectrogramProcessor&>(processor).readAnalysis(*spectrum);const auto&f=spectrum->measurement;const juce::Rectangle<float>plot(131,214,761,263),gram(1042,214,490,263);blank(g,plot);blank(g,gram);blank(g,{1551,228,37,244});if(valid){const float range=processor.state.getRawParameterValue("displayRange")->load();const double history=processor.state.getRawParameterValue("history")->load(),nyquist=f.sampleRate*.5;juce::Path path,held;bool started=false;for(int i=1;i<f.bins;++i){const double hz=i*f.sampleRate/f.fftSize;if(hz<20)continue;const float x=plot.getX()+float(std::log(hz/20)/std::log(nyquist/20))*plot.getWidth();const auto y=[&](float db){return plot.getBottom()-std::clamp((db+range)/range,0.f,1.f)*plot.getHeight();};if(!started){started=true;path.startNewSubPath(x,y(f.db[size_t(i)]));held.startNewSubPath(x,y(f.heldDb[size_t(i)]));}else {path.lineTo(x,y(f.db[size_t(i)]));held.lineTo(x,y(f.heldDb[size_t(i)]));}}g.setColour(juce::Colours::cyan);g.strokePath(path,juce::PathStrokeType(1.6f));if(f.settings.maxHold){g.setColour(juce::Colours::orange);g.strokePath(held,juce::PathStrokeType(1.3f));}const bool depth=processor.state.getRawParameterValue("depthView")->load()>.5f;for(unsigned j=0;j<spectrum->count;++j){const auto col=(spectrum->cursor+SpectrumDisplay::columns-spectrum->count+j)%SpectrumDisplay::columns;const double age=f.timeSeconds-spectrum->times[col];if(age<0||age>history)continue;const float x=gram.getRight()-float(age/history)*gram.getWidth();if(depth){juce::Path ridge;for(int row=0;row<SpectrumDisplay::rows;++row){const float level=std::clamp((spectrum->spectrogram[col][size_t(row)]+range)/range,0.f,1.f),px=gram.getX()+row*gram.getWidth()/(SpectrumDisplay::rows-1),py=gram.getBottom()-float(age/history)*gram.getHeight()*.75f-level*gram.getHeight()*.2f;if(row)ridge.lineTo(px,py);else ridge.startNewSubPath(px,py);}if(j%6==0){g.setColour(juce::Colours::cyan.withAlpha(.55f));g.strokePath(ridge,juce::PathStrokeType(1));}}else for(int row=0;row<SpectrumDisplay::rows;++row){const float level=std::clamp((spectrum->spectrogram[col][size_t(row)]+range)/range,0.f,1.f);g.setColour(juce::Colour::fromHSV(.66f*(1-level),1,level,1));g.fillRect(x,gram.getBottom()-(row+1)*gram.getHeight()/SpectrumDisplay::rows,std::max(1.f,gram.getWidth()*.1f/float(history)),gram.getHeight()/SpectrumDisplay::rows+1);}}meter(g,{1551,228,37,244},f.peakDb,true);}text(g,{1490,765,136,31},numberText(f.peakHz,valid),19);text(g,{1490,832,136,29},numberText(f.peakDb,valid),19);blank(g,{131,478,762,28});if(valid){g.setFont(13);g.setColour(juce::Colour(0xff7999a9));for(double hz:{20.,50.,100.,200.,500.,1000.,2000.,5000.,10000.,20000.})if(hz<=f.sampleRate*.5){const float x=plot.getX()+float(std::log(hz/20)/std::log(f.sampleRate*.5/20))*plot.getWidth();g.drawText(hz<1000?juce::String(int(hz)):juce::String(hz/1000,0)+"k",int(x)-18,479,38,20,juce::Justification::centred);}}else text(g,{131,478,762,28},"WAITING FOR AUDIO",16);text(g,{1090,478,399,24},valid?juce::String(f.timeSeconds,2)+" s  | dropped "+juce::String(spectrum->dropped):"WAITING FOR AUDIO",16);}
 void paintDelta(juce::Graphics&g){auto&p=static_cast<DeltaMonitorProcessor&>(processor);const auto f=p.deltaSnapshot();const bool valid=p.processingReady()&&f.referenceValid;const bool history=valid&&p.readAnalysis(*delta);blank(g,{1310,218,118,248});for(int c=0;c<2;++c){meter(g,{float(78+c*55),221,43,232},f.dryPeak[size_t(c)],valid);meter(g,{float(1170+c*51),221,42,232},f.processedPeak[size_t(c)],p.processingReady()&&f.frameEnd>0);meter(g,{float(1312+c*51),221,42,232},f.deltaPeak[size_t(c)],valid);}text(g,{79,477,104,26},numberText(std::max(f.dryPeak[0],f.dryPeak[1]),valid));text(g,{1161,477,120,26},numberText(std::max(f.processedPeak[0],f.processedPeak[1]),p.processingReady()&&f.frameEnd>0));text(g,{1310,477,120,26},numberText(std::max(f.deltaPeak[0],f.deltaPeak[1]),valid));blank(g,{1474,217,116,245});if(valid&&f.correlationValid){g.setColour(juce::Colours::cyan);g.fillRect(1482.f,339-f.correlation*114,100.f,3.f);}text(g,{1483,477,111,26},numberText(f.correlation,valid&&f.correlationValid));blank(g,{288,203,824,282});if(history){for(size_t c=0;c<3;++c){g.setColour(c==0?juce::Colours::cyan:c==1?juce::Colours::orange:juce::Colours::lightgreen);for(unsigned j=0;j<delta->count;++j){auto i=(delta->cursor+DeltaDisplay::columns-delta->count+j)%DeltaDisplay::columns;const float x=290+819*j/float(std::max(1u,delta->count-1));g.drawVerticalLine(int(x),344-std::clamp(delta->maximum[c][i],-1.f,1.f)*130,344-std::clamp(delta->minimum[c][i],-1.f,1.f)*130);}}}text(g,{425,488,564,25},valid?"DRY / PROCESSED / DELTA | "+juce::String(delta->count*64/processor.actualRate.load()*1000,1)+" ms":"REFERENCE UNAVAILABLE",17);blank(g,{1480,831,58,49});if(valid&&std::max(f.deltaPeak[0],f.deltaPeak[1])>-90){g.setColour(juce::Colours::cyan);g.fillEllipse(1495,840,25,25);}}
 AnalysisProcessor&processor;int number;juce::Image art;FoundationLook look;HardwareLookAndFeel comboLook;std::vector<std::unique_ptr<Control>>controls;juce::Label processedSource;std::unique_ptr<LoudnessDisplay>loud;std::unique_ptr<SpectrumDisplay>spectrum;std::unique_ptr<DeltaDisplay>delta;
